package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.history.ViewAsOf;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeople {
    public void respond(@Val SheetResponse sheet, @Val ViewAsOf asOf, SheetHistory history,
            ObjectResponse<List<PersonResponse>> response) {
        response.send(history.view(sheet.id(), asOf.on(), jdbc -> new PersonRepository(jdbc).list(sheet.id()).stream()
                .map(PersonResponse::from).toList()));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A person, with the grade in force on the sheet's today and every grade they were given (each from its from-date), their statement count and their last statement's due-total ("n/a" when it had none) and date
 *  (both null before their first statement), the date they are retired from (null: not retired), whether they have any hold and their holds (in the order added), their patrons' names, sorted, their patrons with their shares of 100.00, sorted by name, their own terms (null: none), their contact (null: none) and their aliases, sorted as names are compared. */
public record PersonResponse(long id, String name, String grade, List<GradeResponse> grades, long version, int statementCount, String statedTotal,
        String statementDate, String retiredFrom, boolean held, List<HoldResponse> holds,
        List<String> patrons, List<PatronShareResponse> patronShares, Integer terms, String contact, List<String> aliases) {
    public static PersonResponse from(Person person) {
        Statements s = person.getStatements();
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(),
                person.getGrades().stream().map(GradeResponse::from).toList(), person.getVersion(), s.count(),
                s.count() == 0 ? null : s.lastDueTotal() == null ? "n/a" : s.lastDueTotal().toPlainString(),
                s.lastDate() == null ? null : s.lastDate().toString(),
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(), person.isHeld(),
                person.getHolds().stream().map(HoldResponse::from).toList(),
                person.getPatrons(), person.getPatronShares().stream().map(PatronShareResponse::from).toList(),
                person.getTerms(), person.getContact(), person.getAliases());
    }
}

    /** The sheet's rates, by grade, then by from-date (none first). */
    public List<Rate> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, grade, rate, from_date, to_date FROM rate WHERE sheet_id = ?"
                + " ORDER BY grade, from_date NULLS FIRST", ROW, sheetId);
    }

    /** The sheet, then its parent, its parent's parent, and so on up to {@link #PARENT_LEVELS} levels up. */
    public List<String> ancestry(String sheetId) {
        List<String> found = new java.util.ArrayList<>(List.of(sheetId));
        String at = sheetId;
        while (found.size() <= PARENT_LEVELS) {
            String parent = parentOf(at);
            if (parent == null || found.contains(parent)) {
                break;
            }
            found.add(parent);
            at = parent;
        }
        return found;
    }

